const x = $input.first().json;

const youtubeUrl = String(x["YouTube video URL"] || "").trim();

let videoId = null;

// Direct video ID
if (/^[A-Za-z0-9_-]{11}$/.test(youtubeUrl)) {
  videoId = youtubeUrl;
}

// Standard youtube.com/watch?v=...
if (!videoId) {
  const watchMatch = youtubeUrl.match(
    /youtube\.com\/watch\?v=([A-Za-z0-9_-]{11})/
  );

  if (watchMatch) {
    videoId = watchMatch[1];
  }
}

// youtu.be/...
if (!videoId) {
  const shortMatch = youtubeUrl.match(
    /youtu\.be\/([A-Za-z0-9_-]{11})/
  );

  if (shortMatch) {
    videoId = shortMatch[1];
  }
}

// Shorts / embed / live
if (!videoId) {
  const pathMatch = youtubeUrl.match(
    /youtube\.com\/(?:shorts|embed|live)\/([A-Za-z0-9_-]{11})/
  );

  if (pathMatch) {
    videoId = pathMatch[1];
  }
}

if (!videoId) {
  throw new Error(
    `Invalid YouTube URL or video ID. Received: ${youtubeUrl}`
  );
}

const maxComments = Math.min(
  Math.max(
    Number(x["Comments to analyze"] || 100),
    25
  ),
  100
);

const order =
  String(x["Comment selection"] || "relevance") === "time"
    ? "time"
    : "relevance";

return [
  {
    json: {
      videoId,
      videoUrl: `https://www.youtube.com/watch?v=${videoId}`,
      maxComments,
      order,
      minChars: 12,
      runAt: new Date().toISOString()
    }
  }
];

const cfg=$('Prepare Video Data').first().json;
const vr=$('Fetch Video Details').first().json||{};
const cr=$input.first().json||{};
if(vr.error) throw new Error('YouTube video lookup failed.');
if(cr.error) throw new Error('YouTube comments lookup failed. Check the API key and whether comments are enabled.');
const v=vr.items?.[0];
if(!v) throw new Error('Video not found or is not publicly accessible.');

const clean=s=>String(s??'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
const norm=s=>clean(s).toLowerCase().replace(/https?:\/\/\S+/g,'').replace(/[^\p{L}\p{N}\s]/gu,' ').replace(/\s+/g,' ').trim();
const junk=[/^\s*(first|early|anyone here|who else is here)\s*[!.?]*$/i,/^(nice|great|awesome|amazing|love this|thanks|thank you|cool)\s*[!.?]*$/i,/(subscribe to my channel|check out my channel)/i];

const rows=[];
for(const th of (cr.items||[])){
  const top=th?.snippet?.topLevelComment, ts=top?.snippet;
  if(ts?.textOriginal||ts?.textDisplay) rows.push({
    id:top.id||th.id,type:'top_level',author:clean(ts.authorDisplayName||''),
    text:clean(ts.textOriginal||ts.textDisplay),likes:+(ts.likeCount||0),replies:+(th?.snippet?.totalReplyCount||0),
    publishedAt:ts.publishedAt||null
  });
  for(const rep of (th.replies?.comments||[])){
    const rs=rep?.snippet;
    if(rs?.textOriginal||rs?.textDisplay) rows.push({
      id:rep.id,type:'reply',author:clean(rs.authorDisplayName||''),
      text:clean(rs.textOriginal||rs.textDisplay),likes:+(rs.likeCount||0),replies:0,publishedAt:rs.publishedAt||null
    });
  }
}
const seen=new Set(), good=[];
for(const r of rows){
  const n=norm(r.text); if(r.text.length<cfg.minChars||!n||seen.has(n)||junk.some(re=>re.test(r.text))) continue;
  r.e=(r.likes*2)+(r.replies*3); seen.add(n); good.push(r);
}
good.sort((a,b)=>{
  if(cfg.order==='time'){const d=String(b.publishedAt||'').localeCompare(String(a.publishedAt||''));if(d)return d}
  return b.e-a.e
});
const comments=good.slice(0,cfg.maxComments).map((r,i)=>({
  evidence_id:`C${String(i+1).padStart(3,'0')}`,
  comment_id:r.id,author:r.author,type:r.type,text:r.text.slice(0,1200),
  likes:r.likes,replies:r.replies,published_at:r.publishedAt,
  evidence_url:`https://www.youtube.com/watch?v=${cfg.videoId}&lc=${encodeURIComponent(r.id)}`
}));
return [{json:{
  run:{video_id:cfg.videoId,video_url:cfg.videoUrl,collected_rows:rows.length,usable_unique_comments:good.length,comments_sent_to_ai:comments.length},
  video:{title:v.snippet?.title||'Unknown',channel:v.snippet?.channelTitle||'Unknown',published_at:v.snippet?.publishedAt||null,
    view_count:+(v.statistics?.viewCount||0),like_count:+(v.statistics?.likeCount||0),comment_count:+(v.statistics?.commentCount||0)},
  comments
}}];

const ai = $input.first().json || {};
const p = $('Prepare Comments Data').first().json || {};

if (ai.error) throw new Error('AI analysis failed.');

// ---------- helpers ----------
function getAIText(x) {
  if (typeof x.output_text === 'string' && x.output_text.trim()) return x.output_text.trim();
  if (typeof x.output === 'string' && x.output.trim()) return x.output.trim();
  if (Array.isArray(x.output)) {
    return x.output
      .flatMap(i => (Array.isArray(i?.content) ? i.content : []))
      .filter(c => c?.type === 'output_text' && typeof c.text === 'string')
      .map(c => c.text)
      .join('\n')
      .trim();
  }
  return '';
}

function parseJSON(text) {
  if (!text) return null;
  try { return JSON.parse(text); } catch {}
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  if (fenced) { try { return JSON.parse(fenced[1]); } catch {} }
  const s = text.indexOf('{'), e = text.lastIndexOf('}');
  if (s >= 0 && e > s) { try { return JSON.parse(text.slice(s, e + 1)); } catch {} }
  return null;
}

const esc = v => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const num = v => { const n = Number(v); return Number.isFinite(n) ? n.toLocaleString() : '0'; };

const raw = getAIText(ai);
if (!raw) throw new Error('AI Agent returned no usable output.');
const analysis = parseJSON(raw);
if (!analysis) throw new Error('AI Agent did not return valid JSON.');

const run = p.run || {};
const video = p.video || {};
const comments = p.comments || [];
const evidenceMap = new Map(comments.map(c => [c.evidence_id, c]));

const validIds = arr => (Array.isArray(arr) ? arr.filter(id => evidenceMap.has(id)) : []);

// ---------- normalize data ----------
const signals = (analysis.signals || []).slice(0, 7).map(s => {
  const evidenceIds = validIds(s.evidence_ids);
  return {
    title: s.title || s.name || s.signal || s.topic || s.signal_type || 'Audience Signal',
    summary: s.summary || s.description || s.reason || '',
    signalType: s.signal_type || s.type || 'Signal',
    confidence: s.confidence || '',
    evidenceIds,
    quotes: Array.isArray(s.representative_quotes) ? s.representative_quotes : [],
    uniqueCommenters: s.unique_commenters ??
      new Set(evidenceIds.map(id => evidenceMap.get(id)?.author).filter(Boolean)).size,
    totalLikes: s.total_likes ??
      evidenceIds.reduce((sum, id) => sum + Number(evidenceMap.get(id)?.likes || 0), 0),
    mentionCount: s.mention_count ?? evidenceIds.length,
    contentAngle: s.content_angle || s.content_opportunity || '',
    productAngle: s.product_angle || s.product_opportunity || ''
  };
});

const contentOpps = (analysis.content_opportunities || []).slice(0, 5).map(o => ({
  title: o.title || o.idea || 'Content Opportunity',
  reason: o.reason || o.description || '',
  hook: o.hook || '',
  evidenceIds: validIds(o.supporting_evidence_ids)
}));

const productOpps = (analysis.product_opportunities || []).slice(0, 5).map(o => ({
  idea: o.idea || o.title || 'Product / Service Opportunity',
  userProblem: o.user_problem || o.problem || '',
  whyItAppears: o.why_it_appears || o.reason || '',
  evidenceIds: validIds(o.supporting_evidence_ids)
}));

const caveats = Array.isArray(analysis.caveats) ? analysis.caveats : [];

// ---------- design tokens ----------
const C = {
  ink: '#111827', body: '#374151', muted: '#6b7280', line: '#e5e7eb',
  bg: '#f3f4f6', card: '#ffffff', brand: '#4f46e5', brandSoft: '#eef2ff',
  green: '#065f46', greenSoft: '#d1fae5', amber: '#92400e', amberSoft: '#fef3c7'
};

// ---------- UI pieces ----------
const sectionTitle = t => `
  <h2 style="margin:36px 0 14px;font-size:20px;line-height:1.3;font-weight:700;color:${C.ink};">${esc(t)}</h2>`;

const card = inner => `
  <div style="background:${C.card};border:1px solid ${C.line};border-radius:12px;padding:20px;margin:0 0 16px;">${inner}</div>`;

const badge = (t, bg = C.brandSoft, fg = C.brand) => `
  <span style="display:inline-block;background:${bg};color:${fg};font-size:12px;font-weight:700;padding:3px 10px;border-radius:999px;margin:0 6px 6px 0;">${esc(t)}</span>`;

const field = (label, text) => !text ? '' : `
  <div style="margin:14px 0 0;">
    <div style="font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:${C.muted};margin-bottom:3px;">${esc(label)}</div>
    <div style="font-size:15px;line-height:1.6;color:${C.body};">${esc(text)}</div>
  </div>`;

const quoteBlock = q => `
  <div style="margin:10px 0 0;padding:10px 14px;border-left:3px solid ${C.brand};background:#f9fafb;border-radius:0 8px 8px 0;font-size:14px;line-height:1.6;color:${C.body};font-style:italic;">&ldquo;${esc(q)}&rdquo;</div>`;

const chips = ids => {
  if (!ids.length) return '';
  const links = ids.slice(0, 8).map(id => {
    const url = evidenceMap.get(id)?.evidence_url || '';
    return `<a href="${esc(url)}" target="_blank" style="display:inline-block;background:${C.brandSoft};color:${C.brand};text-decoration:none;font-size:12px;font-weight:700;padding:4px 10px;border-radius:6px;margin:0 6px 6px 0;">${esc(id)}</a>`;
  }).join('');
  return `
  <div style="margin:14px 0 0;">
    <div style="font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:${C.muted};margin-bottom:6px;">Evidence</div>
    ${links}
  </div>`;
};

const stat = (label, value) => `
  <div style="display:inline-block;vertical-align:top;width:31%;min-width:140px;margin:0 1% 10px 0;box-sizing:border-box;background:${C.card};border:1px solid ${C.line};border-radius:10px;padding:12px 14px;">
    <div style="font-size:22px;font-weight:700;color:${C.ink};line-height:1.2;">${esc(value)}</div>
    <div style="font-size:12px;color:${C.muted};margin-top:2px;">${esc(label)}</div>
  </div>`;

const miniStat = (label, value) => `
  <span style="display:inline-block;margin:14px 20px 0 0;">
    <span style="font-size:18px;font-weight:700;color:${C.ink};">${esc(value)}</span>
    <span style="font-size:12px;color:${C.muted};"> ${esc(label)}</span>
  </span>`;

const button = (href, label) => `
  <table role="presentation" cellspacing="0" cellpadding="0" border="0" style="margin-top:16px;">
    <tr><td bgcolor="${C.brand}" style="border-radius:8px;">
      <a href="${esc(href)}" target="_blank" style="display:inline-block;padding:12px 22px;font-size:15px;font-weight:700;color:#ffffff;text-decoration:none;border-radius:8px;">&#9654;&nbsp; Open YouTube Video</a>
    </td></tr>
  </table>`;

const confidenceBadge = c => {
  const v = String(c).toLowerCase();
  if (v.includes('high')) return badge(`Confidence: ${c}`, C.greenSoft, C.green);
  if (v.includes('low')) return badge(`Confidence: ${c}`, '#fee2e2', '#991b1b');
  return badge(`Confidence: ${c}`, C.amberSoft, C.amber);
};

// ---------- build HTML ----------
let body = '';

// Header
body += `
<div style="background:${C.card};border:1px solid ${C.line};border-radius:14px;padding:24px;">
  <div style="font-size:12px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:${C.brand};">YouTube Audience Intelligence</div>
  <h1 style="margin:8px 0 6px;font-size:26px;line-height:1.25;font-weight:800;color:${C.ink};">${esc(video.title || 'YouTube Video')}</h1>
  <div style="font-size:15px;color:${C.muted};">${esc(video.channel || '')}</div>
  ${run.video_url ? button(run.video_url, 'Open YouTube Video') : ''}
</div>`;

// Overview
body += sectionTitle('Overview');
body += `<div style="font-size:0;">
  ${stat('Comments analyzed', num(run.comments_sent_to_ai))}
  ${stat('Usable comments', num(run.usable_unique_comments))}
  ${stat('Total comments', num(video.comment_count))}
  ${stat('Views', num(video.view_count))}
  ${stat('Likes', num(video.like_count))}
</div>`;

// Executive summary
body += sectionTitle('Executive Summary');
body += card(`<div style="font-size:16px;line-height:1.7;color:${C.body};">${esc(analysis.executive_summary || 'No executive summary was generated.')}</div>`);

// Signals
body += sectionTitle('Audience Signals');
if (!signals.length) {
  body += card(`<strong style="color:${C.ink};">No strong audience signals were detected.</strong>`);
}
signals.forEach((s, i) => {
  body += card(`
    <div style="font-size:12px;font-weight:700;color:${C.muted};margin-bottom:4px;">SIGNAL ${i + 1}</div>
    <h3 style="margin:0 0 10px;font-size:19px;line-height:1.35;font-weight:700;color:${C.ink};">${esc(s.title)}</h3>
    ${badge(s.signalType)}${s.confidence ? confidenceBadge(s.confidence) : ''}
    ${field('What the audience is saying', s.summary)}
    <div>
      ${miniStat('mentions', num(s.mentionCount))}
      ${miniStat('unique commenters', num(s.uniqueCommenters))}
      ${miniStat('likes', num(s.totalLikes))}
    </div>
    ${field('Content angle', s.contentAngle)}
    ${field('Product / service angle', s.productAngle)}
    ${s.quotes.length ? `
      <div style="margin:14px 0 0;">
        <div style="font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:${C.muted};">Representative comments</div>
        ${s.quotes.slice(0, 2).map(quoteBlock).join('')}
      </div>` : ''}
    ${chips(s.evidenceIds)}
  `);
});

// Content opportunities
body += sectionTitle('Content Opportunities');
if (!contentOpps.length) {
  body += card(`<span style="color:${C.body};">No content opportunities identified.</span>`);
}
contentOpps.forEach((o, i) => {
  body += card(`
    <div style="font-size:12px;font-weight:700;color:${C.muted};margin-bottom:4px;">IDEA ${i + 1}</div>
    <h3 style="margin:0;font-size:18px;line-height:1.35;font-weight:700;color:${C.ink};">${esc(o.title)}</h3>
    ${field('Why', o.reason)}
    ${o.hook ? `<div style="margin:14px 0 0;">
      <div style="font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:${C.muted};margin-bottom:3px;">Hook</div>
      <div style="font-size:15px;line-height:1.6;color:${C.ink};font-weight:600;font-style:italic;">&ldquo;${esc(o.hook)}&rdquo;</div>
    </div>` : ''}
    ${chips(o.evidenceIds)}
  `);
});

// Product opportunities
body += sectionTitle('Product / Service Opportunities');
if (!productOpps.length) {
  body += card(`<span style="color:${C.body};">No product or service opportunities were identified from the available evidence.</span>`);
}
productOpps.forEach((o, i) => {
  body += card(`
    <div style="font-size:12px;font-weight:700;color:${C.muted};margin-bottom:4px;">OPPORTUNITY ${i + 1}</div>
    <h3 style="margin:0;font-size:18px;line-height:1.35;font-weight:700;color:${C.ink};">${esc(o.idea)}</h3>
    ${field('User problem', o.userProblem)}
    ${field('Why it appears', o.whyItAppears)}
    ${chips(o.evidenceIds)}
  `);
});

// Caveats
body += sectionTitle('Caveats');
body += card(
  caveats.length
    ? `<ul style="margin:0;padding-left:20px;font-size:15px;line-height:1.7;color:${C.body};">${caveats.map(c => `<li style="margin-bottom:6px;">${esc(c)}</li>`).join('')}</ul>`
    : `<span style="color:${C.body};">Analysis is limited to the comments collected in this run.</span>`
);

// Footer
body += `
<p style="margin:24px 0 0;text-align:center;font-size:12px;line-height:1.6;color:${C.muted};">
  Analysis generated from ${num(run.comments_sent_to_ai)} collected YouTube comments.<br>
  Every evidence link points back to the original YouTube comment.
</p>`;

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(video.title || 'YouTube Audience Intelligence')}</title>
</head>
<body style="margin:0;padding:0;background:${C.bg};">
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background:${C.bg};">
  <tr><td align="center" style="padding:20px 12px;">
    <div style="width:100%;max-width:680px;text-align:left;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,Helvetica,sans-serif;font-size:15px;line-height:1.6;color:${C.body};">
      ${body}
    </div>
  </td></tr>
</table>
</body>
</html>`;

return [
  {
    json: {
      status: 'success',
      videoId: run.video_id || null,
      videoUrl: run.video_url || null,
      videoTitle: video.title || null,
      analyzedComments: run.comments_sent_to_ai || 0,
      analysis,
      reportHtml: html,
      generatedAt: new Date().toISOString()
    }
  }
];

